// caller passes source='anarlog_title' (intentionally or via param
// injection), this query returns empty rather than leaking weak
// discovery rows into the per-source UI.
func (q *Queries) ListUnmatchedExternalContacts(ctx context.Context, arg ListUnmatchedExternalContactsParams) ([]*ExternalContact, error) {
	rows, err := q.db.Query(ctx, ListUnmatchedExternalContacts,
		arg.Source,
		arg.IncludeUnresolvedTelegram,
		arg.PageOffset,
		arg.PageLimit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []*ExternalContact{}
	for rows.Next() {
		var i ExternalContact
		if err := rows.Scan(
			&i.ID,
			&i.Source,
			&i.SourceID,
			&i.AccountID,
			&i.DisplayName,
			&i.FirstName,
			&i.LastName,
			&i.Emails,
			&i.Phones,
			&i.Addresses,
			&i.Organization,
			&i.JobTitle,
			&i.Birthday,
			&i.PhotoUrl,
			&i.CrmContactID,
			&i.MatchStatus,
			&i.DuplicateOfID,
			&i.Etag,
			&i.Metadata,
			&i.SyncedAt,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.DeletedAt,
			&i.HostID,
			&i.LastContentHash,
			&i.PendingMethodSuggestions,
			&i.DismissedMethodSuggestions,
		); err != nil {
			return nil, err
		}
		items = append(items, &i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

